import React from 'react';
import './styles/globals.css';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import About from './components/About';
import Skills from './components/Skills';
import Projects from './components/Projects';
import Services from './components/Services';
import Contact from './components/Contact';
// About, Skills, Services are fully implemented components

function App() {
  return (
    <div className="App">
      <Navbar />
      <Hero />
      <div className="divider" />
      <About />
      <div className="divider" />
      <Skills />
      <div className="divider" />
      <Projects />
      <div className="divider" />
      <Services />
      <div className="divider" />
      <Contact />
      <footer style={{
        borderTop: '1px solid rgba(255,107,26,0.15)',
        padding: '2rem 5%',
        textAlign: 'center',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        maxWidth: '100%'
      }}>
        <div style={{ fontWeight: 800, fontSize: '0.9rem' }}>
          Bisrat <span style={{ color: 'var(--orange)' }}>Amare</span>
        </div>
        <p style={{ color: 'var(--muted)', fontSize: '0.75rem' }}>
          © {new Date().getFullYear()} — Full-Stack Software Engineer · Ethiopia
        </p>
        <div style={{ display: 'flex', gap: '1rem' }}>
          {[
            { label: 'GH', href: 'https://github.com/Bisrat12Amare' },
            { label: 'TG', href: 'https://t.me/BisratLe12' },
            { label: '@', href: 'mailto:bisratamare88@gmail.com' }
          ].map(link => (
            <a key={link.label} href={link.href} style={{
              width: 36, height: 36,
              border: '1px solid rgba(255,107,26,0.15)',
              borderRadius: 6,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              color: 'var(--muted)', textDecoration: 'none',
              fontSize: '0.8rem', fontWeight: 700,
              transition: 'all 0.2s'
            }}
            onMouseEnter={e => {
              e.target.style.borderColor = 'var(--orange)';
              e.target.style.color = 'var(--orange)';
            }}
            onMouseLeave={e => {
              e.target.style.borderColor = 'rgba(255,107,26,0.15)';
              e.target.style.color = 'var(--muted)';
            }}>
              {link.label}
            </a>
          ))}
        </div>
      </footer>
    </div>
  );
}

export default App;
